    }

    fn diagnostic(ctx: &RuleContext<Self>, _state: &Self::State) -> Option<RuleDiagnostic> {
        let call = ctx.query();

        Some(
            RuleDiagnostic::new(
                rule_category!(),
                call.range(),
                markup! {
                    "Implied eval() is not allowed."
                },
            )
