/// Returns `true` if the given callee refers to one of the implied-eval functions,
/// either as a direct global call or accessed through the `window`/`globalThis` objects.
fn is_implied_eval_callee(expr: &AnyJsExpression, model: &SemanticModel) -> bool {
    match expr {
        AnyJsExpression::JsIdentifierExpression(_) => is_global_implied_eval_identifier(expr, model),
        AnyJsExpression::JsStaticMemberExpression(member_expr) => {
            is_global_static_member(member_expr, model)
        }
        AnyJsExpression::JsComputedMemberExpression(computed_member_expr) => {
            is_global_computed_member(computed_member_expr, model)
        }
        AnyJsExpression::JsParenthesizedExpression(paren_expr) => paren_expr
            .expression()
            .ok()
            .is_some_and(|inner| is_implied_eval_callee(&inner, model)),
        _ => false,
    }
}

/// Handles `setTimeout(...)` where the identifier is the global function and isn't shadowed.
fn is_global_implied_eval_identifier(expr: &AnyJsExpression, model: &SemanticModel) -> bool {
    let Some((reference, name)) = global_identifier(expr) else {
        return false;
    };

    is_implied_eval_function(name.text()) && model.binding(&reference).is_none()
}

/// Handles `window.setTimeout(...)` and chained global access such as `window.window.setTimeout(...)`.
fn is_global_static_member(member_expr: &JsStaticMemberExpression, model: &SemanticModel) -> bool {
